+	 * per import), so sharing one copy across sessions would break them.
+	 */
+	private async claimInstance(
+		entry: PluginEntry,
+		exportName: string | undefined,
+	): Promise<AgentExtension> {
+		const spare = entry.spare;
+		if (spare) {
+			entry.spare = undefined;
+			return spare;
+		}
