+			if (typeof hook !== "function") continue;
+			const phase: PluginErrorPhase = `hook:${hookName}`;
+			wrapped[hookName] = async (...args: unknown[]) => {
+				if (!this.isUsable(entry, generation, instance)) {
+					return undefined;
+				}
