+				try {
+					const result = await runWithTimeout(
+						() =>
+							runInPluginScope(scope, () =>
+								(hook as HookFn).apply(hooks, args),
+							),
+						this.hookTimeoutMs,
+						`Plugin "${entry.name}" ${phase}`,
+					);
